                          onClick: async (e) => {
                            e.preventDefault();
                            setMsg('');
                            setErr('');
                            try {
                              const res = await fetchDshModels();
                              if (res && res.models && res.models.length > 0) {
                                setDshModels(res.models);
                                setMsg(`已刷新模型列表，找到 ${res.models.length} 个模型`);
                              } else {
                                setDshModels(PRESET_DSH_MODELS);
                                setMsg('已切换至内置预设模型列表');
                              }
                            } catch (err) {
                              setDshModels(PRESET_DSH_MODELS);
                              setErr(`自动获取 DSH 模型失败 (${err.message || String(err)})，已回退至预设列表`);
                            }
                          },
