//#region src/monitor/retention.ts
/** 固定身份集合的行留存 */
var RowRetention = class {
	retainRounds;
	/** 身份键 → 最近一次采样到的代表行与连续未采样轮数 */
	entries = /* @__PURE__ */ new Map();
	/** 被手动移除的身份(仅内存;该身份再次采样到时自动清除) */
	removed = /* @__PURE__ */ new Set();
	/** 构造留存:轮数必须为正整数(配置面另有 5 至 60 的范围校验) */
	constructor(retainRounds) {
		this.retainRounds = retainRounds;
		if (!Number.isInteger(retainRounds) || retainRounds < 1) throw new Error(`行留存轮数必须为正整数,收到 ${retainRounds}`);
	}
	/** 当前留存的身份数(诊断与测试用) */
	get size() {
		return this.entries.size;
	}
	/** 某身份是否处于手动移除状态(诊断与测试用) */
	isRemoved(key) {
		return this.removed.has(key);
	}
	/**
	* 推进一轮,返回本轮应显示的行:
	* 本轮采样到的行在前(保持传入顺序),未采样的零值行按身份首次出现顺序在后;
	* 未采样行连续达到 `retainRounds` 轮即从留存中移除。
	*/
	advance(current) {
		const present = /* @__PURE__ */ new Set();
		const representative = /* @__PURE__ */ new Map();
		for (const item of current) {
			present.add(item.key);
			this.removed.delete(item.key);
			const best = representative.get(item.key);
			if (best === void 0 || item.weight > best.weight) representative.set(item.key, item);
		}
		for (const [key, item] of representative) this.entries.set(key, {
			row: item.row,
			misses: 0
		});
		for (const [key, entry] of [...this.entries]) {
			if (present.has(key)) continue;
			entry.misses += 1;
			if (entry.misses >= this.retainRounds) this.entries.delete(key);
		}
		const rows = [];
		for (const item of current) {
			if (this.removed.has(item.key)) continue;
			rows.push({
				row: item.row,
				sampled: true
			});
		}
		for (const [key, entry] of this.entries) {
			if (present.has(key) || this.removed.has(key)) continue;
			rows.push({
				row: entry.row,
				sampled: false
			});
		}
		return rows;
	}
	/** 手动移除一个身份(不持久化;该身份再次被采样到时自动补回) */
	remove(key) {
		this.removed.add(key);
		this.entries.delete(key);
	}
};
