/** 归入「宿主」组的保留键(宿主进程承载全部会话,不能归给某一个会话) */
const HOST_GROUP_KEY = "\0host";
/** 归入「未归因」组的保留键 */
const UNATTRIBUTED_GROUP_KEY = "\0unattributed";
/**
* 归入「子代理」合计行的保留键:
* 会话维度卡把全部子代理并成一行(逐个展示子代理是子代理维度卡的事,
* 否则会话卡会成为子代理卡的超集),故该行需要一个稳定的身份键供行留存记账。
*/
const SUBAGENT_GROUP_KEY = "\0subagents";
/** 格式化为 yyyy-MM-dd HH:mm:ss+HH:mm */
function formatDateTime(value) {
	const date = new Date(value);
	const pad = (n, width = 2) => String(n).padStart(width, "0");
	const offset = -date.getTimezoneOffset();
	const sign = offset >= 0 ? "+" : "-";
	const abs = Math.abs(offset);
	const zone = `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`;
	return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${zone}`;
}
/** 字节数按量级自适应单位(KB/MB/GB,两位小数) */
function formatBytes(bytes) {
	const kilobytes = bytes / 1024;
	if (kilobytes < 1024) return `${kilobytes.toFixed(2)}KB`;
	const megabytes = kilobytes / 1024;
	if (megabytes < 1024) return `${megabytes.toFixed(2)}MB`;
	return `${(megabytes / 1024).toFixed(2)}GB`;
}
/**
* 当前生效的泳道预备色(长度等于本轮需要配色的普通成员数):
* 面板在渲染各卡之前按取色方案算出颜色并写入此处,占比条、表格色块与图例因此同源。
*/
let activeLaneColors = DEFAULT_LANE_COLOR_POOL;
